<template><AppPage :title="summary?.zone.provenance.name || 'Zone'" subtitle="Bidirectional physical and workload topology"><v-alert v-if="error" type="error" variant="tonal">{{ error }}</v-alert><v-skeleton-loader v-else-if="loading" type="heading,card"/><template v-else-if="summary"><v-alert v-if="summary.gaps.length" type="warning" variant="tonal" class="mb-4" title="Partial zone topology">{{ summary.gaps.map(g=>`${g.area}: ${g.state}`).join(' · ') }}</v-alert><div class="metrics"><div v-for="item in metrics" :key="item[0]"><span>{{ item[0] }}</span><strong>{{ item[1] }}</strong></div></div><v-card variant="outlined" class="mt-5"><v-card-title>Relationships</v-card-title><v-card-text><TopologyRelations v-if="graph" :graph="graph" :root-key="summary.zone.key"/><p v-else>No relationship graph is available.</p></v-card-text></v-card></template></AppPage></template>
<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { sreApi,type SreGraph,type SreZoneSummary } from '@/api/sre';import AppPage from '@/components/app/AppPage.vue';import TopologyRelations from '@/components/sre/TopologyRelations.vue'
const route=useRoute(),summary=ref<SreZoneSummary|null>(null),graph=ref<SreGraph|null>(null),loading=ref(true),error=ref<string|null>(null)
const metrics=computed(()=>summary.value?[['Management nodes',summary.value.managementNodes],['Compute nodes',summary.value.computeNodes],['Storage nodes',summary.value.storageNodes],['Machine pools',summary.value.machinePools],['Volume pools',summary.value.volumePools],['Hosted VMs',summary.value.hostedVms],['Dependent Shoots',summary.value.dependentShoots]]:[])
onMounted(async()=>{try{const name=String(route.params.zone),[detail,list]=await Promise.all([sreApi.zone(name),sreApi.zones()]);summary.value=detail.data;const id=list.data.find(item=>item.resource.provenance.name===name)?.id;if(id)graph.value=(await sreApi.graph(id)).data}catch(cause){error.value=cause instanceof Error?cause.message:'Zone unavailable'}finally{loading.value=false}})
</script>
<style scoped>.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metrics>div{padding:14px;border:1px solid var(--ic-border);border-radius:8px}.metrics span{display:block;color:var(--ic-text-muted);font-size:11px;text-transform:uppercase}.metrics strong{font-size:24px}@media(max-width:700px){.metrics{grid-template-columns:1fr 1fr}}</style>
